import hashlib, json, os, platform, signal, subprocess, time
from pathlib import Path
assert Path('/.dockerenv').is_file(), 'container only'
root=Path('/results')
root.mkdir(exist_ok=True)
def run_read(cmd):
    return subprocess.check_output(cmd,text=True).strip()
def digest(file):
    return hashlib.sha256(Path(file).read_bytes()).hexdigest()
versions={'old':'0.5.2','new':'0.6.0'}
binaries={}
for version in versions:
    target=Path('/work')/version/'target/release'
    matches=[p for p in (target/'deps').glob('benchmark-*') if p.is_file() and os.access(p,os.X_OK) and p.suffix!='.d']
    assert len(matches)==1, matches
    binaries[version]={'benchmark':str(matches[0]),'server':str(target/'bench_echo_server')}
    for key in ('benchmark','server'):
        binaries[version][key+'_sha256']=digest(binaries[version][key])
    binaries[version]['cargo_lock_sha256']=digest(Path('/work')/version/'Cargo.lock')
assert binaries['old']['benchmark_sha256']!=binaries['new']['benchmark_sha256']
assert binaries['old']['server_sha256']!=binaries['new']['server_sha256']
meta={
 'study_date':'2026-11-04','base_commit':'04447fb3dcc17f76e535d98a820668420293cded',
 'versions':versions,'binaries':binaries,
 'environment':{'uname':run_read(['uname','-a']),'os_release':Path('/etc/os-release').read_text(),
 'cores':os.cpu_count(),'rust':run_read(['/root/.cargo/bin/rustc','--version']),
 'tc':run_read(['tc','-V']),'tcp':{key:Path('/proc/sys/net/ipv4/'+key).read_text().strip() for key in ('tcp_congestion_control','tcp_sack')},
 'network':'bridge; NET_ADMIN; no host network or mounts; qdisc only on isolated container lo; 4 CPU limit'},
 'method':{'model':1,'clients':[1,32],'payload_bytes':128,'rounds':3,'warmup_secs':1,'duration_secs':5,'drain_ms':500,'command_timeout_secs':180,
 'order':'round -> scenario -> version (old,new on even round+scenario, new,old otherwise) -> transport (tcp,kcp on odd rounds, kcp,tcp on even rounds); serial, no builds during measurement',
 'scenarios':['clean','delay20','loss1','loss5','loss10','loss20','loss30'],
 'kcp':'fast; nodelay/10ms/fastresend=2/nocwnd, snd/rcv=32/128, MTU=1400; no parameter changes',
 'netem':'10ms each direction for non-clean; random loss with seed42; limit10000; no bandwidth limit; reset per invocation',
 'accounting':'requests independently counted after local enqueue, window determined by send start; payload checked replies only; received-only RTT quantiles; 500ms tail is not a strict wall-clock deadline; qdisc includes setup/warmup/both cells',
 'comparison':'new paired end-to-end measurements, not replayed packet traces; host not a dedicated benchmark machine; historical 0.5.2 stored separately'},
}
runs=[]
artifact=root/'study.json'
def save():
    artifact.write_text(json.dumps({'meta':meta,'runs':runs},indent=2)+'\n')
def reset():
    p=subprocess.run(['tc','qdisc','del','dev','lo','root'],capture_output=True,text=True)
    if p.returncode and 'No such file' not in p.stderr and 'Cannot delete qdisc with handle of zero' not in p.stderr:
        raise RuntimeError(p.stderr)
    return run_read(['tc','qdisc','show','dev','lo'])
def measure(round_no, scenario_index, scenario, version, transport, payload=128, study='main'):
    clean=reset()
    qcmd=[]
    if scenario!='clean':
        qcmd=['tc','qdisc','add','dev','lo','root','netem','limit','10000','delay','10ms']
        if scenario.startswith('loss'): qcmd+=['loss','random',scenario[4:]+'%','seed','42']
        subprocess.run(qcmd,check=True)
    name=f'{study}-{scenario}-{version}-{transport}-{round_no}'
    output=root/(name+'.json')
    command=[binaries[version]['benchmark'],'--model','1','--clients','1,32','--warmup','1','--duration','5','--payload',str(payload),'--json',str(output)]
    env=os.environ.copy(); env['LYNN_BENCH_TRANSPORT']=transport; env['LYNN_BENCH_KCP_MODE']='fast'; env.pop('LYNN_BENCH_LOGS',None)
    started=time.time(); timed_out=False
    with (root/(name+'.log')).open('w') as log:
        p=subprocess.Popen(command,stdout=log,stderr=subprocess.STDOUT,env=env,start_new_session=True)
        try: code=p.wait(timeout=180)
        except subprocess.TimeoutExpired:
            timed_out=True; os.killpg(p.pid,signal.SIGKILL); p.wait(); code=124
    qdisc=run_read(['tc','-s','qdisc','show','dev','lo'])
    (root/(name+'.qdisc')).write_text(qdisc+'\n')
    record={'name':name,'study':study,'round':round_no,'scenario':scenario,'dependency':versions[version],'transport':transport,'payload_bytes':payload,'command':command,'netem_command':qcmd,'started_unix':started,'ended_unix':time.time(),'exit_code':code,'timed_out':timed_out,'qdisc':qdisc,'loadavg_after':Path('/proc/loadavg').read_text().strip(),'output':None}
    if output.exists():
        try: record['output']=json.loads(output.read_text())
        except Exception as exc: record['parse_error']=str(exc)
    if code!=0: record['log']=(root/(name+'.log')).read_text()
    runs.append(record); save()
    print(name,'exit='+str(code),flush=True)
try:
    save()
    for round_no in range(1,4):
        for scenario_index,scenario in enumerate(meta['method']['scenarios']):
            order=('old','new') if (round_no+scenario_index)%2==0 else ('new','old')
            transports=('tcp','kcp') if round_no%2 else ('kcp','tcp')
            for version in order:
                for transport in transports: measure(round_no,scenario_index,scenario,version,transport)
    # A separate, explicitly labelled multi-fragment workload, not mixed with 128-byte history.
    for round_no in range(1,4):
        for scenario_index,scenario in enumerate(('clean','loss5')):
            for version in (('old','new') if round_no%2 else ('new','old')):
                measure(round_no,scenario_index,scenario,version,'kcp',16384,'large-payload')
finally:
    meta['final_qdisc']=reset(); save()
print('STUDY_FINISHED',flush=True)

